def resample_linear(values, positions):
    n = len(values)
    result = []
    for x in positions:
        if x < 0 or x > n - 1:
            continue
        if x == int(x):
            result.append(values[int(x)])
        else:
            i = int(x)
            if i + 1 < n:
                result.append(values[i] + (x - i) * (values[i+1] - values[i]))
            else:
                result.append(values[i])
    return result
